<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApp} from '../store';import {stateFor} from '@jp/core';const route=useRoute();const router=useRouter();const app=useApp();const ignored=computed(()=>route.path==='/ignored');const book=ref('');const lesson=ref('');watch(book,()=>lesson.value='');const lessons=computed(()=>app.data.lessons.filter(l=>!book.value||l.bookId===book.value));const words=computed(()=>app.data.words.filter(w=>{const s=stateFor(app.data,w.id);return (ignored.value?s?.isIgnored:s?.isDifficult)&&(!book.value||lessons.value.some(l=>l.id===w.lessonId))&&(!lesson.value||w.lessonId===lesson.value)}));async function study(){await app.start('difficult',lesson.value?[lesson.value]:lessons.value.map(l=>l.id));router.push('/study')}
</script>
<template><section class="page-heading"><div><p class="eyebrow">A LITTLE MORE ATTENTION</p><h1>{{ignored?'忽略列表':'我的生词本'}}</h1><p class="muted">{{ignored?'暂时跳过的词，随时可以恢复学习。':'值得多见几次的词，留在这里慢慢熟悉。'}}</p></div><button v-if="!ignored" class="primary" :disabled="!words.some(w=>!stateFor(app.data,w.id)?.isIgnored)||app.busy" @click="study">开始学习生词 →</button></section><div class="tabs"><RouterLink to="/difficult">生词本</RouterLink><RouterLink to="/ignored">忽略列表</RouterLink></div><div class="selection-tools"><div class="actions"><label>词书<select v-model="book"><option value="">全部词书</option><option v-for="b in app.data.books" :key="b.id" :value="b.id">{{b.title}}</option></select></label><label>课次<select v-model="lesson"><option value="">全部课次</option><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></select></label></div><span>{{words.length}} 个词</span></div><div v-if="!words.length" class="empty">{{ignored?'没有被忽略的单词。':'还没有生词。在学习时点击书签，就能收藏到这里。'}}</div><div v-for="w in words" :key="w.id" class="word-row"><div><h3 lang="ja">{{w.term}} <small>{{w.reading}}</small></h3><p>{{w.meaning}}</p><small>{{app.data.lessons.find(l=>l.id===w.lessonId)?.title}}{{!ignored&&stateFor(app.data,w.id)?.isIgnored?' · 已忽略，不参与练习':''}}</small></div><button :disabled="app.busy" @click="app.flag(w.id,ignored?'isIgnored':'isDifficult',false)">{{ignored?'恢复学习':'取消生词'}}</button></div></template>
